def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_defects = sum(1 for x in op if x == 'D')
    my_defects = sum(1 for x in my if x == 'D')

    # Detect opponent's last-move defection and run length
    last_my, last_op = history[-1]
    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    # Opponent mirrors our prior action (TFT-like): if we cooperated and they defected, they may be TFT.
    # In that case, respond to their D with D but return to C quickly to escape mutual defection.
    if last_op == 'D':
        # A single opponent defection: retaliate once, then probe cooperation
        if run_d == 1 and opp_defects <= max(2, n // 4):
            # if we already retaliated last round, try cooperation to recover
            if last_my == 'D':
                return 'C'
            return 'D'
        # sustained defection: keep defecting
        if run_d >= 2:
            return 'D'
        if opp_defects * 4 >= n * 3:
            return 'D'
        # otherwise retaliate then plan recovery next round
        if last_my == 'D':
            return 'C'
        return 'D'

    # Opponent last cooperated.
    # If we defected last round, return to cooperation to rebuild CC.
    if last_my == 'D':
        return 'C'

    # If opponent has never defected and we've been cooperative, mostly cooperate;
    # exploit only rarely, and stop exploiting if they punish.
    if opp_defects == 0:
        if n >= 90:
            return 'C'
        # occasional gentle probe, low frequency
        if n > 20 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Moderate/defecting opponent: cooperate when their recent behavior is cooperative
    recent = op[-8:] if n >= 8 else op
    recent_d = sum(1 for x in recent if x == 'D')
    if recent_d == 0:
        return 'C'
    if recent_d * 2 >= len(recent):
        return 'D'
    # near-threshold: probe cooperation with high probability
    if rng.random() < 0.6:
        return 'C'
    return 'D'
